/// What `print(_:)` writes for `items`, without the newline.
private func printed(_ items: Any...) -> String {
    items.map { String(describing: $0) }.joined(separator: " ")
}

// Sources/ECS/ECS.docc/GettingStarted.md:26
fileprivate struct Position: Component { var x: Double, y: Double }

fileprivate struct Velocity: Component { var dx: Double, dy: Double }

fileprivate struct Health: Component { var current: Int }

// Sources/ECS/ECS.docc/GettingStarted.md:113
@System
fileprivate struct Movement {
    func run(_ movers: Update<Position>.Over<Velocity>) {
        movers { position, row in
            position.x += row.components.dx
            position.y += row.components.dy
        }
    }
}

@System
fileprivate struct Reaper {
    func run(_ living: Query<Health>, commands: inout Commands) {
        for (entity, health) in living where health.current <= 0 {
            commands.despawn(entity)
        }
    }
}

